const PAYLOAD = [{"id":"personnages-verite-chasseurs-az","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"La faucheuse noire","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Angelus"],"pnj":{"real_name":"Az","nom_verite":"Azraël","race":"Angelus","age":"« ?? ans » - ??? ans","origine":"???","statut":"Chasseurs","statut_verite":"La Mort","relations":["Elynea","Mammon"],"source_group":"Association","source_order":0,"identity_keys":["la faucheuse noire","az","azrael"],"source_verite":[{"label":"Informations Vérité","text":"Azraël était une Archange principale du Paradis. Extrêmement importante pour Elynea, on ne sait pas vraiment si, comme Elynea, elle n’était pas une fille de dieux d’Aèr, tel que Threisis, la rumeur qui semble la plus récurrente reste toutefois une paladine de Threisis, archange noir sur Aèr que sa hiérarchie empêchait de progresser et qui fut séduite par les promesses d’Elynea. Son opposition avec Mammon fut régulière et paradoxalement sans haine aucune, ni l’un l’autre n’avait d’amour pour la guerre et chacun faisait son devoir, petit à petit, cessant de s’opposer pour s’allier. Là encore, on ne sait pas vraiment ce qu’il s’est passé, mais Azraël a été arrachée du paradis et dépossédée d’une grande partie de ses pouvoirs. Les anges des autres factions parlent de sa trahison, en collaborant avec Mammon, elle aurait conspiré contre Elynea et l’aurait payé en étant trahie par le Démon, qui la déposséda de ses pouvoirs en ayant trahi la longue collaboration menée. Les anges de sa faction sont plus discrets, murmurant plutôt la trahison de Gabriel, jalouse d’Azrael. Gabriel et Barachiel auraient conspiré pour se débarrasser d’elle en prétextant son rapprochement avec Mammon. Les anges de Michael, Archange qui était proche d’Azrael, murmurent de leur côté qu’Azraël n’aurait été ni trahie ni n’aurait trahi le paradis, elle aurait sacrifié ses pouvoirs face à un Fléau qu’elle maintiendrait encore en sommeil, forcée de le surveiller sur Terre ; Actuellement, elle est la n°1 des Hunt-15, à ce jour, aucune proie ne lui a échappée, l’Archange de la Mort ne laissant aucune chance à ce qu’elle traque. Elle n’est pas invulnérable pour autant et de nombreux anges et démons s‘essaient à l’attaquer."}],"source_extract":"La faucheuse noire\nLa Mort\nNom de la Réalité : Az\nNom de la Vérité : Azraël\nAge : « ?? ans » - ??? ans\nAffiliations :\nChasseurs\nNationalité d’origine : ???\nEthnie réelle : Angelus\nPersonnages liés :\n Elynea\n Mammon\n___________________________________________________________________________\nInformations Vérité :\nAzraël était une Archange principale du Paradis.\nExtrêmement importante pour Elynea, on ne sait pas vraiment si, comme Elynea, elle n’était pas une\nfille de dieux d’Aèr, tel que Threisis, la rumeur qui semble la plus récurrente reste toutefois une\npaladine de Threisis, archange noir sur Aèr que sa hiérarchie empêchait de progresser et qui fut\nséduite par les promesses d’Elynea.\nSon opposition avec Mammon fut régulière et paradoxalement sans haine aucune, ni l’un l’autre\nn’avait d’amour pour la guerre et chacun faisait son devoir, petit à petit, cessant de s’opposer pour\ns’allier.\nLà encore, on ne sait pas vraiment ce qu’il s’est passé, mais Azraël a été arrachée du paradis et\ndépossédée d’une grande partie de ses pouvoirs.\nLes anges des autres factions parlent de sa trahison, en collaborant avec Mammon, elle aurait\nconspiré contre Elynea et l’aurait payé en étant trahie par le Démon, qui la déposséda de ses\npouvoirs en ayant trahi la longue collaboration menée.\nLes anges de sa faction sont plus discrets, murmurant plutôt la trahison de Gabriel, jalouse d’Azrael.\nGabriel et Barachiel auraient conspiré pour se débarrasser d’elle en prétextant son rapprochement\navec Mammon.\nLes anges de Michael, Archange qui était proche d’Azrael, murmurent de leur côté qu’Azraël n’aurait\nété ni trahie ni n’aurait trahi le paradis, elle aurait sacrifié ses pouvoirs face à un Fléau qu’elle\nmaintiendrait encore en sommeil, forcée de le surveiller sur Terre ;\nActuellement, elle est la n°1 des Hunt-15, à ce jour, aucune proie ne lui a échappée, l’Archange de la\nMort ne laissant aucune chance à ce qu’elle traque.\nElle n’est pas invulnérable pour autant et de nombreux anges et démons s‘essaient à l’attaquer.","source_heading":"La faucheuse noire"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Az"],["Nom de la Vérité","Azraël"],["Âge","« ?? ans » - ??? ans"],["Affiliations","Chasseurs"],["Nationalité d’origine","???"],["Nature réelle","Angelus"],["Personnages liés","Elynea · Mammon"],["Repère","La Mort"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Azraël était une Archange principale du Paradis. Extrêmement importante pour Elynea, on ne sait pas vraiment si, comme Elynea, elle n’était pas une fille de dieux d’Aèr, tel que Threisis, la rumeur qui semble la plus récurrente reste toutefois une paladine de Threisis, archange noir sur Aèr que sa hiérarchie empêchait de progresser et qui fut séduite par les promesses d’Elynea. Son opposition avec Mammon fut régulière et paradoxalement sans haine aucune, ni l’un l’autre n’avait d’amour pour la guerre et chacun faisait son devoir, petit à petit, cessant de s’opposer pour s’allier. Là encore, on ne sait pas vraiment ce qu’il s’est passé, mais Azraël a été arrachée du paradis et dépossédée d’une grande partie de ses pouvoirs. Les anges des autres factions parlent de sa trahison, en collaborant avec Mammon, elle aurait conspiré contre Elynea et l’aurait payé en étant trahie par le Démon, qui la déposséda de ses pouvoirs en ayant trahi la longue collaboration menée. Les anges de sa faction sont plus discrets, murmurant plutôt la trahison de Gabriel, jalouse d’Azrael. Gabriel et Barachiel auraient conspiré pour se débarrasser d’elle en prétextant son rapprochement avec Mammon. Les anges de Michael, Archange qui était proche d’Azrael, murmurent de leur côté qu’Azraël n’aurait été ni trahie ni n’aurait trahi le paradis, elle aurait sacrifié ses pouvoirs face à un Fléau qu’elle maintiendrait encore en sommeil, forcée de le surveiller sur Terre ; Actuellement, elle est la n°1 des Hunt-15, à ce jour, aucune proie ne lui a échappée, l’Archange de la Mort ne laissant aucune chance à ce qu’elle traque. Elle n’est pas invulnérable pour autant et de nombreux anges et démons s‘essaient à l’attaquer."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-anna-hita","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"L’achimage suprême","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Mages"],"pnj":{"real_name":"Anna HITA","nom_verite":"Anahita","race":"Mages","age":"« ???ans » - ??? ans","origine":"???","statut":"Chasseurs","statut_verite":"L’être de Magie","relations":[],"source_group":"Association","source_order":1,"identity_keys":["l'achimage supreme","anna hita","anahita"],"source_verite":[{"label":"Informations Vérité","text":"Anahita est une Mage, elle est extrêmement ancienne et remonte à une époque reculée. Elle n’est pas humaine, c’est une créature de la Terre aussi ancienne que les dieux locaux, une « Voyageuses », tels les Titans, les croquemitaines, les Amazones et tant de « monstres » possédant des Mageius. Anahita reste singulière, car elle n’est pas « dotée » d’un ou plusieurs Mageius, mais son âme est un amas de ces derniers. Elle connait parfaitement les Dieux et les Archanges, mais aussi les très anciens seigneurs Voyageurs, elle a vu apparaitre les vampires, elle connait parfaitement les Atlantes et les expatriés, elle connait tout de la Terre en vérité. On ignore les projets réels d’Anahita et la faction des Mages la considère comme son ultime et plus puissante représentante, car ses savoirs et ses affinités sont infinis. Cependant, peu de Magisters révèlent son existence aux mages plus humbles et pratiquement aucun « Disciple » (sorcier servant les Mages) n’est vraiment au courant de son existence. Anahita ne préside aucune Loge, en revanche, elle n’a aucun scrupule à s’inviter partout à sa guise, au demeurant, elle le fait aussi bien chez les vampires, ayant fermé la crypte profonde d’un Duc nazi en 1941 au nez et à la barbe de ce dernier. Anahita ne peut avoir d’enfant, étant un être créé par la Magie mais à part, elle ne peut engendrer la vie mais la magie seulement, elle peut créer des Mageius et c’est en cela qu’elle a une relation très singulière avec les Mages, si elle est la plus puissante et la plus respectée, toutes les Loges cherchent un moyen de la capturer et l’asservir pour qu’elle ne produise des Mageius même si, pour elle, cela s’apparente à une grossesse « magique », ce qu’elle n’a guère envie de subir, le processus étant long et éprouvant, elle serait, ainsi, la « mère » du Mageius qu’avait autrefois Merlin, sa plus grande création, mais aussi de celui de Faust, sa pire erreur. C’est la n°2 du Hunt-15, pour elle, la chasse est un divertissement plus qu’autre chose."}],"source_extract":"L’achimage suprême\nL’être de Magie\nNom de la Réalité : Anna HITA\nNom de la Vérité : Anahita\nAge : « ???ans » - ??? ans\nAffiliations :\nChasseurs\nNationalité d’origine : ???\nEthnie réelle : Mages\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nAnahita est une Mage, elle est extrêmement ancienne et remonte à une époque reculée.\nElle n’est pas humaine, c’est une créature de la Terre aussi ancienne que les dieux locaux, une\n« Voyageuses », tels les Titans, les croquemitaines, les Amazones et tant de « monstres » possédant\ndes Mageius. Anahita reste singulière, car elle n’est pas « dotée » d’un ou plusieurs Mageius, mais\nson âme est un amas de ces derniers.\nElle connait parfaitement les Dieux et les Archanges, mais aussi les très anciens seigneurs Voyageurs,\nelle a vu apparaitre les vampires, elle connait parfaitement les Atlantes et les expatriés, elle connait\ntout de la Terre en vérité.\nOn ignore les projets réels d’Anahita et la faction des Mages la considère comme son ultime et plus\npuissante représentante, car ses savoirs et ses affinités sont infinis. Cependant, peu de Magisters\nrévèlent son existence aux mages plus humbles et pratiquement aucun « Disciple » (sorcier servant\nles Mages) n’est vraiment au courant de son existence.\nAnahita ne préside aucune Loge, en revanche, elle n’a aucun scrupule à s’inviter partout à sa guise,\nau demeurant, elle le fait aussi bien chez les vampires, ayant fermé la crypte profonde d’un Duc nazi\nen 1941 au nez et à la barbe de ce dernier.\nAnahita ne peut avoir d’enfant, étant un être créé par la Magie mais à part, elle ne peut engendrer la\nvie mais la magie seulement, elle peut créer des Mageius et c’est en cela qu’elle a une relation très\nsingulière avec les Mages, si elle est la plus puissante et la plus respectée, toutes les Loges cherchent\nun moyen de la capturer et l’asservir pour qu’elle ne produise des Mageius même si, pour elle, cela\ns’apparente à une grossesse « magique », ce qu’elle n’a guère envie de subir, le processus étant long\net éprouvant, elle serait, ainsi, la « mère » du Mageius qu’avait autrefois Merlin, sa plus grande\ncréation, mais aussi de celui de Faust, sa pire erreur.\nC’est la n°2 du Hunt-15, pour elle, la chasse est un divertissement plus qu’autre chose.","source_heading":"L’achimage suprême"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Anna HITA"],["Nom de la Vérité","Anahita"],["Âge","« ???ans » - ??? ans"],["Affiliations","Chasseurs"],["Nationalité d’origine","???"],["Nature réelle","Mages"],["Repère","L’être de Magie"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Anahita est une Mage, elle est extrêmement ancienne et remonte à une époque reculée. Elle n’est pas humaine, c’est une créature de la Terre aussi ancienne que les dieux locaux, une « Voyageuses », tels les Titans, les croquemitaines, les Amazones et tant de « monstres » possédant des Mageius. Anahita reste singulière, car elle n’est pas « dotée » d’un ou plusieurs Mageius, mais son âme est un amas de ces derniers. Elle connait parfaitement les Dieux et les Archanges, mais aussi les très anciens seigneurs Voyageurs, elle a vu apparaitre les vampires, elle connait parfaitement les Atlantes et les expatriés, elle connait tout de la Terre en vérité. On ignore les projets réels d’Anahita et la faction des Mages la considère comme son ultime et plus puissante représentante, car ses savoirs et ses affinités sont infinis. Cependant, peu de Magisters révèlent son existence aux mages plus humbles et pratiquement aucun « Disciple » (sorcier servant les Mages) n’est vraiment au courant de son existence. Anahita ne préside aucune Loge, en revanche, elle n’a aucun scrupule à s’inviter partout à sa guise, au demeurant, elle le fait aussi bien chez les vampires, ayant fermé la crypte profonde d’un Duc nazi en 1941 au nez et à la barbe de ce dernier. Anahita ne peut avoir d’enfant, étant un être créé par la Magie mais à part, elle ne peut engendrer la vie mais la magie seulement, elle peut créer des Mageius et c’est en cela qu’elle a une relation très singulière avec les Mages, si elle est la plus puissante et la plus respectée, toutes les Loges cherchent un moyen de la capturer et l’asservir pour qu’elle ne produise des Mageius même si, pour elle, cela s’apparente à une grossesse « magique », ce qu’elle n’a guère envie de subir, le processus étant long et éprouvant, elle serait, ainsi, la « mère » du Mageius qu’avait autrefois Merlin, sa plus grande création, mais aussi de celui de Faust, sa pire erreur. C’est la n°2 du Hunt-15, pour elle, la chasse est un divertissement plus qu’autre chose."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-isabella-mironescu","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"La Cartomancienne","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association"],"pnj":{"real_name":"Isabella MIRONESCU","nom_verite":"Isabella MIRONESCU","race":"???","age":"« ?? ans » - ???ans","origine":"Roumaine","statut":"Chasseurs","statut_verite":"Le tarot de la folie","relations":[],"source_group":"Association","source_order":2,"identity_keys":["la cartomancienne","isabella mironescu"],"source_verite":[{"label":"Informations Vérité","text":"??? (à définir) Elle est nu°3 du Hunt-15"}],"source_extract":"La Cartomancienne\nLe tarot de la folie\nNom de la Réalité : Isabella MIRONESCU\nNom de la Vérité : Isabella MIRONESCU\nAge : « ?? ans » - ???ans\nAffiliations :\nChasseurs\nNationalité d’origine : Roumaine\nEthnie réelle : ???\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\n??? (à définir)\nElle est nu°3 du Hunt-15","source_heading":"La Cartomancienne"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Isabella MIRONESCU"],["Nom de la Vérité","Isabella MIRONESCU"],["Âge","« ?? ans » - ???ans"],["Affiliations","Chasseurs"],["Nationalité d’origine","Roumaine"],["Nature réelle","???"],["Repère","Le tarot de la folie"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"??? (à définir) Elle est nu°3 du Hunt-15"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-iwashita-koji","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Le dragon des cieux","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Humaine- Atlante"],"pnj":{"real_name":"IWASHITA Koji","nom_verite":"","race":"Humaine- Atlante","age":"«42 ans » -","origine":"Américano-japonaise","statut":"« Chasseurs » et « Deathrunner »","statut_verite":"La foudre de Tokyo","relations":[],"source_group":"Association","source_order":3,"identity_keys":["le dragon des cieux","iwashita koji"],"source_verite":[{"label":"Informations Vérité","text":"Koji est un demi-Aseryn, un peu comme Veronica silver. Sa mère étant souvent mobilisée durant son enfance, il l’a assez peu connu durant son enfance, et quand il arriva à ses 10 ans, elle ne revint pas au Japon, tombée amoureuse d’un frère d’arme, elle resta aux Etats-Unis, abandonnant Koji qui resta dans sa famille paternelle. Sa famille gardait un katana maudit, « Musaboken » depuis des siècles. Son grand-père connaissait les légendes mais se refusait à y croire, ne les ayant enseignés qu’à son second fils, quand il décéda. L’ancien fut massacré par une créature qui s’empara du katana, Nobuyori, le père, les raconta à Koji, convaincu que son grand-père avait été tué à cause du sabre. Koji avait une telle colère qu’il ne s’interrogea pas sur la véracité de ces légendes, à 17 ans, il s’enfonça dans un repaire Yakuza, sachant qu’il s’agissait peut-être de « yokai », il les tua tous sans retrouver le katana mais frôla la mort. Heureusement pour lui, une Miko le sauva et l’empêcha d’être retrouvé par la police. Instruit auprès du prêtre que la Miko servait, un exorciste Shintoïste, le « Shinryu » s’éleva vite comme un des chasseurs les plus efficaces, intégrant le « Hunt XV », pour le compte de l’Association. Il dispose d’une armure technologique rétractable et prototype, la seule au monde capable de suivre ses mouvements surhumains. Il possède aussi ainsi que deux sabres modernes, capables de générer de la foudre qu’il sait d’instinct orienter. Il ne sait pas qu’il est Aseryn par sa mère, en revanche, il se pense sincèrement descendre de Susanoo, le dieu de l’orage… S’il travaille pour la Blanchisserie à l’occasion, c’est le n°5 des Hunt-15, il rayonne essentiellement en Asie et aux Etats-Unis, c’est le mortel le plus haut dans les chasseurs de l’Association. Bien que formé comme un chasseur Shintoïste, il travaille pour l’Association, car il ne désespère pas de retrouver « Musaboken » dans les mains d’une créature et suspecte la mystérieuse Fuyumi SHIMEKO de le détenir chez les Yakuzas."}],"source_extract":"Le dragon des cieux\nLa foudre de Tokyo\nNom de la Réalité : IWASHITA Koji\nNom de la Vérité : _\nAge : «42 ans » -\nAffiliations :\n« Chasseurs » et « Deathrunner »\nNationalité d’origine : Américano-japonaise\nEthnie réelle : Humaine- Atlante\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nKoji est un demi-Aseryn, un peu comme Veronica silver. Sa mère étant souvent mobilisée durant son\nenfance, il l’a assez peu connu durant son enfance, et quand il arriva à ses 10 ans, elle ne revint pas\nau Japon, tombée amoureuse d’un frère d’arme, elle resta aux Etats-Unis, abandonnant Koji qui resta\ndans sa famille paternelle.\nSa famille gardait un katana maudit, « Musaboken » depuis des siècles. Son grand-père connaissait\nles légendes mais se refusait à y croire, ne les ayant enseignés qu’à son second fils, quand il décéda.\nL’ancien fut massacré par une créature qui s’empara du katana, Nobuyori, le père, les raconta à Koji,\nconvaincu que son grand-père avait été tué à cause du sabre. Koji avait une telle colère qu’il ne\ns’interrogea pas sur la véracité de ces légendes, à 17 ans, il s’enfonça dans un repaire Yakuza,\nsachant qu’il s’agissait peut-être de « yokai », il les tua tous sans retrouver le katana mais frôla la\nmort. Heureusement pour lui, une Miko le sauva et l’empêcha d’être retrouvé par la police.\nInstruit auprès du prêtre que la Miko servait, un exorciste Shintoïste, le « Shinryu » s’éleva vite\ncomme un des chasseurs les plus efficaces, intégrant le « Hunt XV », pour le compte de l’Association.\nIl dispose d’une armure technologique rétractable et prototype, la seule au monde capable de suivre\nses mouvements surhumains. Il possède aussi ainsi que deux sabres modernes, capables de générer\nde la foudre qu’il sait d’instinct orienter. Il ne sait pas qu’il est Aseryn par sa mère, en revanche, il se\npense sincèrement descendre de Susanoo, le dieu de l’orage…\nS’il travaille pour la Blanchisserie à l’occasion, c’est le n°5 des Hunt-15, il rayonne essentiellement en\nAsie et aux Etats-Unis, c’est le mortel le plus haut dans les chasseurs de l’Association.\nBien que formé comme un chasseur Shintoïste, il travaille pour l’Association, car il ne désespère pas\nde retrouver « Musaboken » dans les mains d’une créature et suspecte la mystérieuse Fuyumi\nSHIMEKO de le détenir chez les Yakuzas.","source_heading":"Le dragon des cieux"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","IWASHITA Koji"],["Nom de la Vérité","_"],["Âge","«42 ans » -"],["Affiliations","« Chasseurs » et « Deathrunner »"],["Nationalité d’origine","Américano-japonaise"],["Nature réelle","Humaine- Atlante"],["Repère","La foudre de Tokyo"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Koji est un demi-Aseryn, un peu comme Veronica silver. Sa mère étant souvent mobilisée durant son enfance, il l’a assez peu connu durant son enfance, et quand il arriva à ses 10 ans, elle ne revint pas au Japon, tombée amoureuse d’un frère d’arme, elle resta aux Etats-Unis, abandonnant Koji qui resta dans sa famille paternelle. Sa famille gardait un katana maudit, « Musaboken » depuis des siècles. Son grand-père connaissait les légendes mais se refusait à y croire, ne les ayant enseignés qu’à son second fils, quand il décéda. L’ancien fut massacré par une créature qui s’empara du katana, Nobuyori, le père, les raconta à Koji, convaincu que son grand-père avait été tué à cause du sabre. Koji avait une telle colère qu’il ne s’interrogea pas sur la véracité de ces légendes, à 17 ans, il s’enfonça dans un repaire Yakuza, sachant qu’il s’agissait peut-être de « yokai », il les tua tous sans retrouver le katana mais frôla la mort. Heureusement pour lui, une Miko le sauva et l’empêcha d’être retrouvé par la police. Instruit auprès du prêtre que la Miko servait, un exorciste Shintoïste, le « Shinryu » s’éleva vite comme un des chasseurs les plus efficaces, intégrant le « Hunt XV », pour le compte de l’Association. Il dispose d’une armure technologique rétractable et prototype, la seule au monde capable de suivre ses mouvements surhumains. Il possède aussi ainsi que deux sabres modernes, capables de générer de la foudre qu’il sait d’instinct orienter. Il ne sait pas qu’il est Aseryn par sa mère, en revanche, il se pense sincèrement descendre de Susanoo, le dieu de l’orage… S’il travaille pour la Blanchisserie à l’occasion, c’est le n°5 des Hunt-15, il rayonne essentiellement en Asie et aux Etats-Unis, c’est le mortel le plus haut dans les chasseurs de l’Association. Bien que formé comme un chasseur Shintoïste, il travaille pour l’Association, car il ne désespère pas de retrouver « Musaboken » dans les mains d’une créature et suspecte la mystérieuse Fuyumi SHIMEKO de le détenir chez les Yakuzas."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-alisa-svalisdottir","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"La reine des mille couleurs","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Fléaux"],"pnj":{"real_name":"Alisa SVALISDOTTIR","nom_verite":"Ux'sharith Bellatheis","race":"Fléaux","age":"« ???ans » - ??? ans","origine":"???","statut":"Chasseurs","statut_verite":"Le fléau calamiteux","relations":[],"source_group":"Association","source_order":4,"identity_keys":["la reine des mille couleurs","alisa svalisdottir","ux'sharith bellatheis"],"source_verite":[{"label":"Informations Vérité","text":"Ux’Sharith était un fléau s’étant écrasé sur Terre après la guerre entre les légions, résidu de leur puissance, elle détruisait la lumière aussi bien que la magie en les décomposant. Créature de destruction, elle commandait à Gajh’ shaoggith et C'thath vhadhi, deux fléaux d’une puissance similaire et était soumise « au roi des fléaux » : Mloxol v'aagor, bien que chacun de ces fléaux était une calamité vénérée et crainte n’interagissant que peu avec les autres. Invulnérable, aucun dieu ne parvenait à la vaincre, Lucifer ou même Belial, elle brisait leurs pouvoirs, comme un prime décomposant la lumière. C’est lilith qui se chargea d’elle. Lilith n’usa d’aucun pouvoir, elle vint juste à elle pour la servir, humblement, lui façonner un corps plus humain, touchée, Sharith tomba amoureuse de lilith et usa de plus en plus du corps offert, découvrant la luxure, forçant lilith à faire des corps pour ses deux congénères. Au gré des orgies de Fléaux, elle engendra des myriades de créatures, renforçant les troupes des Fléaux, mais lilith avait gagné, chaque engeance de Sharith emportait de sa puissance avec elle, la créature immonde était si fertile qu’elle s’épuisa sans s’en rendre compte, s’emprisonnant dans le corps conçu pour la retenir. Lilith la tua et chercha à emporter son esprit dans son enfer, mais horrifiée par la trahison, Sharith brisa son esprit pour se réfugier en chaque descendante, chaque descendante se cachant alors et engendrant elle-même des myriades de descendantes. Ces dernières sont appelées sorcières « psycolor » car chacune a hérité d’un pouvoir chromatique, une sorte de ki de fléau augmentant le physique et l’intelligence. L’ordres religieux des saintes Lagunes s’occupa de les traquer et les tuer des millénaires avant de les exploiter plus que els exterminer. En 2020, un grand tournoi au sein de l’Académie visait à établir le niveau des étudiantes psycolors, Allisa SVALISDOTTIR, se révéla posséder l’esprit de Sharith et dévora les pouvoirs de toutes les étudiantes présentes, avant d’anéantir l’ordre des Saintes Lagunes et traquer les sorcières psycolors à travers le monde, n’en gardant qu’une poignée singulière. Profondément marquée par la trahison de son premier amour, Lilith, elle ne se sentit pas de se venger ni reprendre sa vie de fléau, se voyant comme une déesse, l’égale d’Elynea ou Belial, elle vise à purger le monde de sa propre espèce, les Fléau, pour racheter son passé, plus particulièrement, exterminer V’Aagor, son ancien maitre et plus terrible Fléau sur Terre bien que « l ’immondice Abyssale » K'thuhuth'lul l’ait possiblement surpassé."}],"source_extract":"La reine des mille couleurs\nLe fléau calamiteux\nNom de la Réalité : Alisa SVALISDOTTIR\nNom de la Vérité : Ux'sharith Bellatheis\nAge : « ???ans » - ??? ans\nAffiliations :\nChasseurs\nNationalité d’origine : ???\nEthnie réelle : Fléaux\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nUx’Sharith était un fléau s’étant écrasé sur Terre après la guerre entre les légions, résidu de leur\npuissance, elle détruisait la lumière aussi bien que la magie en les décomposant.\nCréature de destruction, elle commandait à Gajh’ shaoggith et C'thath vhadhi, deux fléaux d’une\npuissance similaire et était soumise « au roi des fléaux » : Mloxol v'aagor, bien que chacun de ces\nfléaux était une calamité vénérée et crainte n’interagissant que peu avec les autres.\nInvulnérable, aucun dieu ne parvenait à la vaincre, Lucifer ou même Belial, elle brisait leurs pouvoirs,\ncomme un prime décomposant la lumière. C’est lilith qui se chargea d’elle.\nLilith n’usa d’aucun pouvoir, elle vint juste à elle pour la servir, humblement, lui façonner un corps\nplus humain, touchée, Sharith tomba amoureuse de lilith et usa de plus en plus du corps offert,\ndécouvrant la luxure, forçant lilith à faire des corps pour ses deux congénères. Au gré des orgies de\nFléaux, elle engendra des myriades de créatures, renforçant les troupes des Fléaux, mais lilith avait\ngagné, chaque engeance de Sharith emportait de sa puissance avec elle, la créature immonde était si\nfertile qu’elle s’épuisa sans s’en rendre compte, s’emprisonnant dans le corps conçu pour la retenir.\nLilith la tua et chercha à emporter son esprit dans son enfer, mais horrifiée par la trahison, Sharith\nbrisa son esprit pour se réfugier en chaque descendante, chaque descendante se cachant alors et\nengendrant elle-même des myriades de descendantes.\nCes dernières sont appelées sorcières « psycolor » car chacune a hérité d’un pouvoir chromatique,\nune sorte de ki de fléau augmentant le physique et l’intelligence. L’ordres religieux des saintes\nLagunes s’occupa de les traquer et les tuer des millénaires avant de les exploiter plus que els\nexterminer.\nEn 2020, un grand tournoi au sein de l’Académie visait à établir le niveau des étudiantes psycolors,\nAllisa SVALISDOTTIR, se révéla posséder l’esprit de Sharith et dévora les pouvoirs de toutes les\nétudiantes présentes, avant d’anéantir l’ordre des Saintes Lagunes et traquer les sorcières psycolors\nà travers le monde, n’en gardant qu’une poignée singulière. Profondément marquée par la trahison\nde son premier amour, Lilith, elle ne se sentit pas de se venger ni reprendre sa vie de fléau, se voyant\ncomme une déesse, l’égale d’Elynea ou Belial, elle vise à purger le monde de sa propre espèce, les\nFléau, pour racheter son passé, plus particulièrement, exterminer V’Aagor, son ancien maitre et plus\nterrible Fléau sur Terre bien que « l ’immondice Abyssale » K'thuhuth'lul l’ait possiblement surpassé.","source_heading":"La reine des mille couleurs"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Alisa SVALISDOTTIR"],["Nom de la Vérité","Ux'sharith Bellatheis"],["Âge","« ???ans » - ??? ans"],["Affiliations","Chasseurs"],["Nationalité d’origine","???"],["Nature réelle","Fléaux"],["Repère","Le fléau calamiteux"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Ux’Sharith était un fléau s’étant écrasé sur Terre après la guerre entre les légions, résidu de leur puissance, elle détruisait la lumière aussi bien que la magie en les décomposant. Créature de destruction, elle commandait à Gajh’ shaoggith et C'thath vhadhi, deux fléaux d’une puissance similaire et était soumise « au roi des fléaux » : Mloxol v'aagor, bien que chacun de ces fléaux était une calamité vénérée et crainte n’interagissant que peu avec les autres. Invulnérable, aucun dieu ne parvenait à la vaincre, Lucifer ou même Belial, elle brisait leurs pouvoirs, comme un prime décomposant la lumière. C’est lilith qui se chargea d’elle. Lilith n’usa d’aucun pouvoir, elle vint juste à elle pour la servir, humblement, lui façonner un corps plus humain, touchée, Sharith tomba amoureuse de lilith et usa de plus en plus du corps offert, découvrant la luxure, forçant lilith à faire des corps pour ses deux congénères. Au gré des orgies de Fléaux, elle engendra des myriades de créatures, renforçant les troupes des Fléaux, mais lilith avait gagné, chaque engeance de Sharith emportait de sa puissance avec elle, la créature immonde était si fertile qu’elle s’épuisa sans s’en rendre compte, s’emprisonnant dans le corps conçu pour la retenir. Lilith la tua et chercha à emporter son esprit dans son enfer, mais horrifiée par la trahison, Sharith brisa son esprit pour se réfugier en chaque descendante, chaque descendante se cachant alors et engendrant elle-même des myriades de descendantes. Ces dernières sont appelées sorcières « psycolor » car chacune a hérité d’un pouvoir chromatique, une sorte de ki de fléau augmentant le physique et l’intelligence. L’ordres religieux des saintes Lagunes s’occupa de les traquer et les tuer des millénaires avant de les exploiter plus que els exterminer. En 2020, un grand tournoi au sein de l’Académie visait à établir le niveau des étudiantes psycolors, Allisa SVALISDOTTIR, se révéla posséder l’esprit de Sharith et dévora les pouvoirs de toutes les étudiantes présentes, avant d’anéantir l’ordre des Saintes Lagunes et traquer les sorcières psycolors à travers le monde, n’en gardant qu’une poignée singulière. Profondément marquée par la trahison de son premier amour, Lilith, elle ne se sentit pas de se venger ni reprendre sa vie de fléau, se voyant comme une déesse, l’égale d’Elynea ou Belial, elle vise à purger le monde de sa propre espèce, les Fléau, pour racheter son passé, plus particulièrement, exterminer V’Aagor, son ancien maitre et plus terrible Fléau sur Terre bien que « l ’immondice Abyssale » K'thuhuth'lul l’ait possiblement surpassé."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-luke-cypher","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Le porteur de Lumière","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Daemons"],"pnj":{"real_name":"Luke CYPHER","nom_verite":"Lucifer","race":"Daemons","age":"«34 ans », ????","origine":"???","statut":"« chasseurs »","statut_verite":"L’ange déchu","relations":[],"source_group":"Association","source_order":5,"identity_keys":["le porteur de lumiere","luke cypher","lucifer"],"source_verite":[{"label":"Informations Vérité","text":"Lucifer était un des dieux les plus puissants de l’ancien Pantheon. Héros pendant la guerre contre les fléaux, il était plutôt loyal envers la reine Belial qu’il considérait comme sa sœur. Offusqué qu’elle n’accepte Morrighan dans le panthéon, il s’opposa un peu trop vivement aux décisions de la reine et le paya, Belial n’ayant pas un caractère à tolérer ce genre de discussions. Exilé du « Pandemonium », le grand palais de Belial, où les dieux étaient rassemblés à l’époque, il ne fut autorisé de revenir qu’avec la présentation de nouveaux à la cour de Belial, la reine offrant à son « petit frère », une occasion de se racheter en instruisant la nouvelle protégée de la brune : une minable fille d’une déesse de la lumière d’Aèr. Cette jeune se nommait Elynea, ce n’était pas la seule « petite déesse » qui fut reçue, mais ce fut la seule que Belial garda dans sa cour. Au début, les dieux s’en amusaient, la courtisane n’était qu’une minable visiteuse Belial en l’exposant comme un objet de foire l’humiliait un peu mais c’est Lucifer qui alla le plus loin. Extrêmement jaloux en comprenant le premier qu’Elynea et Belial avaient une relation sérieuse, il se sentit gravement menacé, s’imaginant Belial vouloir qu’il n’enseigne à la jeune déesse pour qu’elle ne devienne déesse de la lumière à sa place afin de le bannir définitivement. Humiliation après humiliation, il tâcha de faire partir Elynea et de briser sa relation avec Belial. Hélas, Lucifer provoqua une haine sans fin chez Elynea pour le panthéon terrestre et si elle s’en alla, ce ne fut que pour mieux conquérir la Terre avec des légions d’Anges. Lucifer fut le premier ciblé, il était celui qu’Elynea connaissait le mieux, presque autant que Belial. Elle se chargea de lui personnellement et le brisa après avoir volé siècle après siècles ses attributs et étouffé ses cultes, les lui prenant. Elle ne s’arrêta pas là, Lucifer devenant un « ange » dans la culture populaire, ne lui laissant même pas la moindre trace d’un passé divin. Désormais, c’est un chasseur du « Hunt-15 », il est perpétuellement harcelé par Uriel, une Archange d’Elynea , aussi sadique qu’attachée à lui, qui, pour achever son humiliation, n’a de cesse de lui proposer de servir Elynea en devenant un simple petit ange… Malgré tout, Lucifer reste loyal à Belial, croyant réellement qu’un jour, elle lui accorderait son aide s’il prouve sa valeur. L’autre objectif de Lucifer, plus égoïste, est de profiter que son corps soi quasi-mortel pour voler l’attribut de la lumière au mortel qui le possède, afin de le garder à jamais. Il manie une épée déicide qu’il créa avec l’aide d’Azraël quand ils s’allièrent pour vaincre le fléau C'thath vhadhi."}],"source_extract":"Le porteur de Lumière\nL’ange déchu\nNom de la Réalité : Luke CYPHER\nNom de la Vérité : Lucifer\nAge : «34 ans », ????\nAffiliations :\n« chasseurs »\nNationalité d’origine : ???\nEthnie réelle : Daemons\nPersonnages liés :\n ?\n________________________________________________________________________\nInformations Vérité :\nLucifer était un des dieux les plus puissants de l’ancien Pantheon.\nHéros pendant la guerre contre les fléaux, il était plutôt loyal envers la reine Belial qu’il considérait\ncomme sa sœur.\nOffusqué qu’elle n’accepte Morrighan dans le panthéon, il s’opposa un peu trop vivement aux\ndécisions de la reine et le paya, Belial n’ayant pas un caractère à tolérer ce genre de discussions.\nExilé du « Pandemonium », le grand palais de Belial, où les dieux étaient rassemblés à l’époque, il ne\nfut autorisé de revenir qu’avec la présentation de nouveaux à la cour de Belial, la reine offrant à son\n« petit frère », une occasion de se racheter en instruisant la nouvelle protégée de la brune : une\nminable fille d’une déesse de la lumière d’Aèr.\nCette jeune se nommait Elynea, ce n’était pas la seule « petite déesse » qui fut reçue, mais ce fut la\nseule que Belial garda dans sa cour. Au début, les dieux s’en amusaient, la courtisane n’était qu’une\nminable visiteuse Belial en l’exposant comme un objet de foire l’humiliait un peu mais c’est Lucifer\nqui alla le plus loin. Extrêmement jaloux en comprenant le premier qu’Elynea et Belial avaient une\nrelation sérieuse, il se sentit gravement menacé, s’imaginant Belial vouloir qu’il n’enseigne à la jeune\ndéesse pour qu’elle ne devienne déesse de la lumière à sa place afin de le bannir définitivement.\nHumiliation après humiliation, il tâcha de faire partir Elynea et de briser sa relation avec Belial.\nHélas, Lucifer provoqua une haine sans fin chez Elynea pour le panthéon terrestre et si elle s’en alla,\nce ne fut que pour mieux conquérir la Terre avec des légions d’Anges. Lucifer fut le premier ciblé, il\nétait celui qu’Elynea connaissait le mieux, presque autant que Belial. Elle se chargea de lui\npersonnellement et le brisa après avoir volé siècle après siècles ses attributs et étouffé ses cultes, les\nlui prenant. Elle ne s’arrêta pas là, Lucifer devenant un « ange » dans la culture populaire, ne lui\nlaissant même pas la moindre trace d’un passé divin.\nDésormais, c’est un chasseur du « Hunt-15 », il est perpétuellement harcelé par Uriel, une Archange\nd’Elynea , aussi sadique qu’attachée à lui, qui, pour achever son humiliation, n’a de cesse de lui\nproposer de servir Elynea en devenant un simple petit ange… Malgré tout, Lucifer reste loyal à Belial,\ncroyant réellement qu’un jour, elle lui accorderait son aide s’il prouve sa valeur. L’autre objectif de\nLucifer, plus égoïste, est de profiter que son corps soi quasi-mortel pour voler l’attribut de la lumière\nau mortel qui le possède, afin de le garder à jamais.\nIl manie une épée déicide qu’il créa avec l’aide d’Azraël quand ils s’allièrent pour vaincre le fléau\nC'thath vhadhi.","source_heading":"Le porteur de Lumière"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Luke CYPHER"],["Nom de la Vérité","Lucifer"],["Âge","«34 ans », ????"],["Affiliations","« chasseurs »"],["Nationalité d’origine","???"],["Nature réelle","Daemons"],["Repère","L’ange déchu"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Lucifer était un des dieux les plus puissants de l’ancien Pantheon. Héros pendant la guerre contre les fléaux, il était plutôt loyal envers la reine Belial qu’il considérait comme sa sœur. Offusqué qu’elle n’accepte Morrighan dans le panthéon, il s’opposa un peu trop vivement aux décisions de la reine et le paya, Belial n’ayant pas un caractère à tolérer ce genre de discussions. Exilé du « Pandemonium », le grand palais de Belial, où les dieux étaient rassemblés à l’époque, il ne fut autorisé de revenir qu’avec la présentation de nouveaux à la cour de Belial, la reine offrant à son « petit frère », une occasion de se racheter en instruisant la nouvelle protégée de la brune : une minable fille d’une déesse de la lumière d’Aèr. Cette jeune se nommait Elynea, ce n’était pas la seule « petite déesse » qui fut reçue, mais ce fut la seule que Belial garda dans sa cour. Au début, les dieux s’en amusaient, la courtisane n’était qu’une minable visiteuse Belial en l’exposant comme un objet de foire l’humiliait un peu mais c’est Lucifer qui alla le plus loin. Extrêmement jaloux en comprenant le premier qu’Elynea et Belial avaient une relation sérieuse, il se sentit gravement menacé, s’imaginant Belial vouloir qu’il n’enseigne à la jeune déesse pour qu’elle ne devienne déesse de la lumière à sa place afin de le bannir définitivement. Humiliation après humiliation, il tâcha de faire partir Elynea et de briser sa relation avec Belial. Hélas, Lucifer provoqua une haine sans fin chez Elynea pour le panthéon terrestre et si elle s’en alla, ce ne fut que pour mieux conquérir la Terre avec des légions d’Anges. Lucifer fut le premier ciblé, il était celui qu’Elynea connaissait le mieux, presque autant que Belial. Elle se chargea de lui personnellement et le brisa après avoir volé siècle après siècles ses attributs et étouffé ses cultes, les lui prenant. Elle ne s’arrêta pas là, Lucifer devenant un « ange » dans la culture populaire, ne lui laissant même pas la moindre trace d’un passé divin. Désormais, c’est un chasseur du « Hunt-15 », il est perpétuellement harcelé par Uriel, une Archange d’Elynea , aussi sadique qu’attachée à lui, qui, pour achever son humiliation, n’a de cesse de lui proposer de servir Elynea en devenant un simple petit ange… Malgré tout, Lucifer reste loyal à Belial, croyant réellement qu’un jour, elle lui accorderait son aide s’il prouve sa valeur. L’autre objectif de Lucifer, plus égoïste, est de profiter que son corps soi quasi-mortel pour voler l’attribut de la lumière au mortel qui le possède, afin de le garder à jamais. Il manie une épée déicide qu’il créa avec l’aide d’Azraël quand ils s’allièrent pour vaincre le fléau C'thath vhadhi."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-hailey-powell","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Hell Soldier","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","humaine"],"pnj":{"real_name":"Hailey POWELL","nom_verite":"","race":"humaine","age":"37 ans","origine":"Américaine","statut":"Deathrunners","statut_verite":"Le cyborg ultime","relations":["Karl HENRY","Leslie WRIGHT"],"source_group":"Association","source_order":6,"identity_keys":["hell soldier","hailey powell"],"source_verite":[{"label":"Informations","text":"Le record d’augmentations posées sur un corps humain n’est pas détenu par A-man mais par une soldate surnommée « Hell », Hailey Powell. Hailey était de la toute première génération, elle été le cobaye d’énormément de tests après avoir été sauvée in extremis de la mort. Elle a été altérée, réparée, envoyée au front, brisée, réparée, renvoyée dans un cycle sans fin pendant toute la guerre, sortant comme seule survivante de sa génération de super soldats du projet « Phoénix » tandis qu’A-man était de la dernière génération du, même projet, la génération « la plus aboutie » où, pourtant, tous sont devenus fous hormis A￾man. Le professeur Yegor KARAMOVICH au sein du PCRC était le principal scientifique sur ce projet moralement abject, voulant garder Hailey pour ses abjectes fantasmes, il la déconnecta après la mort de la grande dirigeante suprême de la Corée du Nord. Officiellement morte, même pour l’armée, Hailey s’est reconnectée seule pour s’échapper des griffes de Karamov. Sans papiers, sans moyen d’en avoir, elle a un logifate déplorable étant trop altérée, bien qu’elle soit plus stable que n’importe qui, pouvant supporter toutes les augmentations. Cette capacité à supporter n’importe quel stress augmentique la rend intéressante par les megacorporations d’armes, telle que Raven, Phoenix ou Owl qui l’engagent surtout pour des tests. Sa véritable tâche reste la Chasse, pour l’Association, elle est un nouveau type de chasseur, dépourvue de tout savoir et toute tradition, elle affronte les créatures avec sa seule intelligence et ses augmentations, ce qui, malgré sa puissance de frappe et de feu, absolument colossale, en fait la moins expérimentée des Chasseurs du Hunt-15, moins expérimentée face à des monstres, c’est pourtant une des meilleures chasseuses au monde. Toutefois, ses principales chasses restent la traque « d’overboosted », des anciens du projet phoenix ou de l’armée coréenne ou des créatures qu’on a augmenté à outrance, car elle est bien plus efficace face à de la mécanique que le reste néanmoins. Un de ses objectifs reste de traquer Karamov, qui continue ses expériences, notamment en ayant ressuscité son frère, lequel aurait fomenté une guerre ouverte entre le Cartel de Sinaloa et la Bratva, Hell n’appréciant en rien de revoir des quasi-zombie de ses camarades ressurgir, parfois 10 ans après leur seconde mort."}],"source_extract":"Hell Soldier\nLe cyborg ultime\nNom : Hailey POWELL\nAge : 37 ans\nAffiliations :\nDeathrunners\nNationalité d’origine : Américaine\nEthnie réelle : humaine\nPersonnages liés :\n Karl HENRY\n Leslie WRIGHT\n___________________________________________________________________________\nInformations :\nLe record d’augmentations posées sur un corps humain n’est pas détenu par A-man mais par une\nsoldate surnommée « Hell », Hailey Powell.\nHailey était de la toute première génération, elle été le cobaye d’énormément de tests après avoir\nété sauvée in extremis de la mort. Elle a été altérée, réparée, envoyée au front, brisée, réparée,\nrenvoyée dans un cycle sans fin pendant toute la guerre, sortant comme seule survivante de sa\ngénération de super soldats du projet « Phoénix » tandis qu’A-man était de la dernière génération\ndu, même projet, la génération « la plus aboutie » où, pourtant, tous sont devenus fous hormis A￾man. Le professeur Yegor KARAMOVICH au sein du PCRC était le principal scientifique sur ce projet\nmoralement abject, voulant garder Hailey pour ses abjectes fantasmes, il la déconnecta après la mort\nde la grande dirigeante suprême de la Corée du Nord.\nOfficiellement morte, même pour l’armée, Hailey s’est reconnectée seule pour s’échapper des griffes\nde Karamov.\nSans papiers, sans moyen d’en avoir, elle a un logifate déplorable étant trop altérée, bien qu’elle soit\nplus stable que n’importe qui, pouvant supporter toutes les augmentations. Cette capacité à\nsupporter n’importe quel stress augmentique la rend intéressante par les megacorporations d’armes,\ntelle que Raven, Phoenix ou Owl qui l’engagent surtout pour des tests.\nSa véritable tâche reste la Chasse, pour l’Association, elle est un nouveau type de chasseur,\ndépourvue de tout savoir et toute tradition, elle affronte les créatures avec sa seule intelligence et\nses augmentations, ce qui, malgré sa puissance de frappe et de feu, absolument colossale, en fait la\nmoins expérimentée des Chasseurs du Hunt-15, moins expérimentée face à des monstres, c’est\npourtant une des meilleures chasseuses au monde.\nToutefois, ses principales chasses restent la traque « d’overboosted », des anciens du projet phoenix\nou de l’armée coréenne ou des créatures qu’on a augmenté à outrance, car elle est bien plus efficace\nface à de la mécanique que le reste néanmoins.\nUn de ses objectifs reste de traquer Karamov, qui continue ses expériences, notamment en ayant\nressuscité son frère, lequel aurait fomenté une guerre ouverte entre le Cartel de Sinaloa et la Bratva,\nHell n’appréciant en rien de revoir des quasi-zombie de ses camarades ressurgir, parfois 10 ans après\nleur seconde mort.","source_heading":"Hell Soldier"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Hailey POWELL"],["Âge","37 ans"],["Affiliations","Deathrunners"],["Nationalité d’origine","Américaine"],["Nature réelle","humaine"],["Personnages liés","Karl HENRY · Leslie WRIGHT"],["Repère","Le cyborg ultime"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Le record d’augmentations posées sur un corps humain n’est pas détenu par A-man mais par une soldate surnommée « Hell », Hailey Powell. Hailey était de la toute première génération, elle été le cobaye d’énormément de tests après avoir été sauvée in extremis de la mort. Elle a été altérée, réparée, envoyée au front, brisée, réparée, renvoyée dans un cycle sans fin pendant toute la guerre, sortant comme seule survivante de sa génération de super soldats du projet « Phoénix » tandis qu’A-man était de la dernière génération du, même projet, la génération « la plus aboutie » où, pourtant, tous sont devenus fous hormis A￾man. Le professeur Yegor KARAMOVICH au sein du PCRC était le principal scientifique sur ce projet moralement abject, voulant garder Hailey pour ses abjectes fantasmes, il la déconnecta après la mort de la grande dirigeante suprême de la Corée du Nord. Officiellement morte, même pour l’armée, Hailey s’est reconnectée seule pour s’échapper des griffes de Karamov. Sans papiers, sans moyen d’en avoir, elle a un logifate déplorable étant trop altérée, bien qu’elle soit plus stable que n’importe qui, pouvant supporter toutes les augmentations. Cette capacité à supporter n’importe quel stress augmentique la rend intéressante par les megacorporations d’armes, telle que Raven, Phoenix ou Owl qui l’engagent surtout pour des tests. Sa véritable tâche reste la Chasse, pour l’Association, elle est un nouveau type de chasseur, dépourvue de tout savoir et toute tradition, elle affronte les créatures avec sa seule intelligence et ses augmentations, ce qui, malgré sa puissance de frappe et de feu, absolument colossale, en fait la moins expérimentée des Chasseurs du Hunt-15, moins expérimentée face à des monstres, c’est pourtant une des meilleures chasseuses au monde. Toutefois, ses principales chasses restent la traque « d’overboosted », des anciens du projet phoenix ou de l’armée coréenne ou des créatures qu’on a augmenté à outrance, car elle est bien plus efficace face à de la mécanique que le reste néanmoins. Un de ses objectifs reste de traquer Karamov, qui continue ses expériences, notamment en ayant ressuscité son frère, lequel aurait fomenté une guerre ouverte entre le Cartel de Sinaloa et la Bratva, Hell n’appréciant en rien de revoir des quasi-zombie de ses camarades ressurgir, parfois 10 ans après leur seconde mort."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-dragoslav-memic","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Le devin","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","humaine"],"pnj":{"real_name":"Dragoslav Memic","nom_verite":"","race":"humaine","age":"34 ans","origine":"Roumaine.","statut":"Neurokillers - chasseurs","statut_verite":"L’intouchable","relations":[],"source_group":"Association","source_order":7,"identity_keys":["le devin","dragoslav memic"],"source_verite":[{"label":"Informations","text":"Dragoslav était un type sans ambition, sans compétences, chauffeur pour un clan mafieux, il se retrouva à Paris, en France, à convoyer des prostituées quand il fut arrêté la première fois. En 2025, il fut finalement blessé d’une balle dans la tête durant la guerre et sa survie fut miraculeuse, récupéré par l’armée américaine, la balle coréenne dans son cerveau était une véritable bombe à retardement pouvant le tuer à tout instant. Incapable de bosser à cause de la balle, il vola l’identité d’un très riche mafieux et se fit opérer aux frais de ce dernier. L’équipe médicale fut abusée par sa fausse identité et paniqua en pensant avoir détruit le cerveau d’un très riche mafieux quand l’opération tourna au plus mal. Afin de le remplacer ce qui avait été endommagé, l’équipe médicale tenta le tout pour le tout en créant le cerveau artificiel le plus complexe jamais créé. Non content d’être sauvé, Dragoslav vit son intelligence nettement avoir été améliorer, sa vitesse de réflexion égaler un ordinateur quantique, sa capacité de traitement des données n’avait plus rien d’humaine. Pourchassé par Sunways pour avoir usurpé une identité ainsi que Krastan GOLOVKIN, le riche mafieux, Dragoslav commença à utiliser son cerveau artificiel pour calculer à un tout autre niveau tous ses gestes et ses actions, ses paroles. Il réalisa en effet qu’avec son cerveau, il pouvait simuler des milliers de fois une situation, qu’elle soit une simple phrase ou un mouvement de combat avant de l’exécuter, rendant ses actions paramétrées au millimètres près. Obsédé par les « données d’entrée », toute information pouvant affiner ses simulations, il devint un hacker réputé. Aucun assassin de la mafia russe ne parvint à le tuer et c’est lui qui finit par avoir Golovkin, volant ses comptes en banque pour se payer un exosquelette, obtenant ainsi de quoi effectuer des mouvements encore plus contrôlés et puissants. Sa capacité à simuler les situations lui permet de pratiquent voir l’avenir, c’est comme ça qu’il a été engagé à la Blanchisserie par une branche de l’Association des chasseurs, Whiteman négocia son « pardon » auprès de la Bratva en échange de contrats spéciaux, qu’il réussit, devenant assez vite un membre du Hunt-15. Même si physiquement, il n’a pas d’aptitude de combat surhumaine ni un armement spécial, il est un des chasseurs les plus difficiles à toucher, même s’il est le plus vulnérable dans les premières secondes d’une confrontation, le temps joue pour lui généralement, compilant toujours de données qui le rendent efficace au fur et à mesure du combat ou de la traque."}],"source_extract":"Le devin\nL’intouchable\nNom : Dragoslav Memic\nAge : 34 ans\nAffiliations :\nNeurokillers - chasseurs\nNationalité d’origine : Roumaine.\nEthnie réelle : humaine\nPersonnages liés :\n ???\n ???\n___________________________________________________________________________\nInformations :\nDragoslav était un type sans ambition, sans compétences, chauffeur pour un clan mafieux, il se\nretrouva à Paris, en France, à convoyer des prostituées quand il fut arrêté la première fois.\nEn 2025, il fut finalement blessé d’une balle dans la tête durant la guerre et sa survie fut\nmiraculeuse, récupéré par l’armée américaine, la balle coréenne dans son cerveau était une véritable\nbombe à retardement pouvant le tuer à tout instant.\nIncapable de bosser à cause de la balle, il vola l’identité d’un très riche mafieux et se fit opérer aux\nfrais de ce dernier. L’équipe médicale fut abusée par sa fausse identité et paniqua en pensant avoir\ndétruit le cerveau d’un très riche mafieux quand l’opération tourna au plus mal.\nAfin de le remplacer ce qui avait été endommagé, l’équipe médicale tenta le tout pour le tout en\ncréant le cerveau artificiel le plus complexe jamais créé.\nNon content d’être sauvé, Dragoslav vit son intelligence nettement avoir été améliorer, sa vitesse de\nréflexion égaler un ordinateur quantique, sa capacité de traitement des données n’avait plus rien\nd’humaine. Pourchassé par Sunways pour avoir usurpé une identité ainsi que Krastan GOLOVKIN, le\nriche mafieux, Dragoslav commença à utiliser son cerveau artificiel pour calculer à un tout autre\nniveau tous ses gestes et ses actions, ses paroles. Il réalisa en effet qu’avec son cerveau, il pouvait\nsimuler des milliers de fois une situation, qu’elle soit une simple phrase ou un mouvement de\ncombat avant de l’exécuter, rendant ses actions paramétrées au millimètres près.\nObsédé par les « données d’entrée », toute information pouvant affiner ses simulations, il devint un\nhacker réputé. Aucun assassin de la mafia russe ne parvint à le tuer et c’est lui qui finit par avoir\nGolovkin, volant ses comptes en banque pour se payer un exosquelette, obtenant ainsi de quoi\neffectuer des mouvements encore plus contrôlés et puissants.\nSa capacité à simuler les situations lui permet de pratiquent voir l’avenir, c’est comme ça qu’il a été\nengagé à la Blanchisserie par une branche de l’Association des chasseurs, Whiteman négocia son\n« pardon » auprès de la Bratva en échange de contrats spéciaux, qu’il réussit, devenant assez vite un\nmembre du Hunt-15.\nMême si physiquement, il n’a pas d’aptitude de combat surhumaine ni un armement spécial, il est un\ndes chasseurs les plus difficiles à toucher, même s’il est le plus vulnérable dans les premières\nsecondes d’une confrontation, le temps joue pour lui généralement, compilant toujours de données\nqui le rendent efficace au fur et à mesure du combat ou de la traque.","source_heading":"Le devin"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Dragoslav Memic"],["Âge","34 ans"],["Affiliations","Neurokillers - chasseurs"],["Nationalité d’origine","Roumaine."],["Nature réelle","humaine"],["Repère","L’intouchable"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Dragoslav était un type sans ambition, sans compétences, chauffeur pour un clan mafieux, il se retrouva à Paris, en France, à convoyer des prostituées quand il fut arrêté la première fois. En 2025, il fut finalement blessé d’une balle dans la tête durant la guerre et sa survie fut miraculeuse, récupéré par l’armée américaine, la balle coréenne dans son cerveau était une véritable bombe à retardement pouvant le tuer à tout instant. Incapable de bosser à cause de la balle, il vola l’identité d’un très riche mafieux et se fit opérer aux frais de ce dernier. L’équipe médicale fut abusée par sa fausse identité et paniqua en pensant avoir détruit le cerveau d’un très riche mafieux quand l’opération tourna au plus mal. Afin de le remplacer ce qui avait été endommagé, l’équipe médicale tenta le tout pour le tout en créant le cerveau artificiel le plus complexe jamais créé. Non content d’être sauvé, Dragoslav vit son intelligence nettement avoir été améliorer, sa vitesse de réflexion égaler un ordinateur quantique, sa capacité de traitement des données n’avait plus rien d’humaine. Pourchassé par Sunways pour avoir usurpé une identité ainsi que Krastan GOLOVKIN, le riche mafieux, Dragoslav commença à utiliser son cerveau artificiel pour calculer à un tout autre niveau tous ses gestes et ses actions, ses paroles. Il réalisa en effet qu’avec son cerveau, il pouvait simuler des milliers de fois une situation, qu’elle soit une simple phrase ou un mouvement de combat avant de l’exécuter, rendant ses actions paramétrées au millimètres près. Obsédé par les « données d’entrée », toute information pouvant affiner ses simulations, il devint un hacker réputé. Aucun assassin de la mafia russe ne parvint à le tuer et c’est lui qui finit par avoir Golovkin, volant ses comptes en banque pour se payer un exosquelette, obtenant ainsi de quoi effectuer des mouvements encore plus contrôlés et puissants. Sa capacité à simuler les situations lui permet de pratiquent voir l’avenir, c’est comme ça qu’il a été engagé à la Blanchisserie par une branche de l’Association des chasseurs, Whiteman négocia son « pardon » auprès de la Bratva en échange de contrats spéciaux, qu’il réussit, devenant assez vite un membre du Hunt-15. Même si physiquement, il n’a pas d’aptitude de combat surhumaine ni un armement spécial, il est un des chasseurs les plus difficiles à toucher, même s’il est le plus vulnérable dans les premières secondes d’une confrontation, le temps joue pour lui généralement, compilant toujours de données qui le rendent efficace au fur et à mesure du combat ou de la traque."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-ciara-mcfarlane","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Le corbeau","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","kelta-humaine"],"pnj":{"real_name":"Ciara MCFARLANE","nom_verite":"Ciara NIMORRIGHAN","race":"kelta-humaine","age":"42 ans","origine":"américano-irlandaise","statut":"religieux et chasseurs","statut_verite":"Les plumes de la victoire","relations":[],"source_group":"Association","source_order":8,"identity_keys":["le corbeau","ciara mcfarlane","ciara nimorrighan"],"source_verite":[{"label":"Informations","text":"Fille de Delwynn McFarlane, un motard des Black Crows du Nevada, elle a toujours baigné dans une ambiance à la fois violente et solennelle, le bikers des BCMC étant d’origine irlandaise et écossaises, ils étaient attachés à des traditions et un code moral. Bien que catholique, Ciara a toujours eu un penchant pour l’occulte. Dès ses 16 ans, elle hérita de la moto de son père, qu’on lui annonça avoir perdu la vie à la suite d’un affrontement entre motards et marchands d’armes russes. Préférant fuir les services sociaux, elle débuta une vie sur la route et fut recueillie quelques années dans une réserve indienne où elle se lia d’amitié avec un jeune nommé Naalnish. Vivant de petites chasses en faisant chasseuse de prime ou de petits boulots, elle se forma un petit réseau chez les amérindiens et les occultistes des Etats-Unis. Officiellement, elle ne fit pas la guerre, officieusement, elle fut déployée au sein d’unités mercenaires que l’armée américaine engagea d’urgence après ses premiers échecs, de la chair à canon pour gagner du temps afin de se redéployer une fois le nouveau matériel produit. Ciara n’apprécia pas l’idée, très vite seule survivante, elle continua de se battre et d’entasser les corps du périmètre qu’elle défendait, n’étant pas officiellement envoyée par les Etats-unis, un groupe d’élite tenta de la tuer quand ils tombèrent sur la zone qu’elle défendait depuis plusieurs mois. Capturée, elle fut rapatriée quand on constata sa survie. Durant les grandes émeutes de 2033, elle gagna le statut de grande druidesse aux yeux de la communauté néopaïenne, extrêmement anarchiste et haïssant toute forme de gouvernance depuis qu’elle s’était faite abandonnée en Corée du Nord. C’est une chasseuse depuis son adolescence néanmoins, fille de la Déesse Morrighan, elle voit à travers l’Hologramme en partie et attire les esprits, disciple de Naalnish, elle nourrit une vénération et une rage contre sa propre mère. Elle s’entraine constamment et ses chasses ne seraient qu’un entrainement pour tenter un jour de mettre une correction à la déesse qui l’abandonna trop tôt. Il est plus probable néanmoins que la semi-déesse se sente surtout obligée de défendre les mortels."}],"source_extract":"Le corbeau\nLes plumes de la victoire\nNom de la Réalité : Ciara MCFARLANE\nNom de la Vérité : Ciara NIMORRIGHAN\nAge : 42 ans\nAffiliations :\nreligieux et chasseurs\nNationalité d’origine : américano-irlandaise\nEthnie réelle : kelta-humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations :\nFille de Delwynn McFarlane, un motard des Black Crows du Nevada, elle a toujours baigné dans une\nambiance à la fois violente et solennelle, le bikers des BCMC étant d’origine irlandaise et écossaises,\nils étaient attachés à des traditions et un code moral.\nBien que catholique, Ciara a toujours eu un penchant pour l’occulte. Dès ses 16 ans, elle hérita de la\nmoto de son père, qu’on lui annonça avoir perdu la vie à la suite d’un affrontement entre motards et\nmarchands d’armes russes.\nPréférant fuir les services sociaux, elle débuta une vie sur la route et fut recueillie quelques années\ndans une réserve indienne où elle se lia d’amitié avec un jeune nommé Naalnish. Vivant de petites\nchasses en faisant chasseuse de prime ou de petits boulots, elle se forma un petit réseau chez les\namérindiens et les occultistes des Etats-Unis.\nOfficiellement, elle ne fit pas la guerre, officieusement, elle fut déployée au sein d’unités mercenaires\nque l’armée américaine engagea d’urgence après ses premiers échecs, de la chair à canon pour\ngagner du temps afin de se redéployer une fois le nouveau matériel produit.\nCiara n’apprécia pas l’idée, très vite seule survivante, elle continua de se battre et d’entasser les\ncorps du périmètre qu’elle défendait, n’étant pas officiellement envoyée par les Etats-unis, un\ngroupe d’élite tenta de la tuer quand ils tombèrent sur la zone qu’elle défendait depuis plusieurs\nmois. Capturée, elle fut rapatriée quand on constata sa survie.\nDurant les grandes émeutes de 2033, elle gagna le statut de grande druidesse aux yeux de la\ncommunauté néopaïenne, extrêmement anarchiste et haïssant toute forme de gouvernance depuis\nqu’elle s’était faite abandonnée en Corée du Nord.\nC’est une chasseuse depuis son adolescence néanmoins, fille de la Déesse Morrighan, elle voit à\ntravers l’Hologramme en partie et attire les esprits, disciple de Naalnish, elle nourrit une vénération\net une rage contre sa propre mère. Elle s’entraine constamment et ses chasses ne seraient qu’un\nentrainement pour tenter un jour de mettre une correction à la déesse qui l’abandonna trop tôt.\nIl est plus probable néanmoins que la semi-déesse se sente surtout obligée de défendre les mortels.","source_heading":"Le corbeau"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Ciara MCFARLANE"],["Nom de la Vérité","Ciara NIMORRIGHAN"],["Âge","42 ans"],["Affiliations","religieux et chasseurs"],["Nationalité d’origine","américano-irlandaise"],["Nature réelle","kelta-humaine"],["Repère","Les plumes de la victoire"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Fille de Delwynn McFarlane, un motard des Black Crows du Nevada, elle a toujours baigné dans une ambiance à la fois violente et solennelle, le bikers des BCMC étant d’origine irlandaise et écossaises, ils étaient attachés à des traditions et un code moral. Bien que catholique, Ciara a toujours eu un penchant pour l’occulte. Dès ses 16 ans, elle hérita de la moto de son père, qu’on lui annonça avoir perdu la vie à la suite d’un affrontement entre motards et marchands d’armes russes. Préférant fuir les services sociaux, elle débuta une vie sur la route et fut recueillie quelques années dans une réserve indienne où elle se lia d’amitié avec un jeune nommé Naalnish. Vivant de petites chasses en faisant chasseuse de prime ou de petits boulots, elle se forma un petit réseau chez les amérindiens et les occultistes des Etats-Unis. Officiellement, elle ne fit pas la guerre, officieusement, elle fut déployée au sein d’unités mercenaires que l’armée américaine engagea d’urgence après ses premiers échecs, de la chair à canon pour gagner du temps afin de se redéployer une fois le nouveau matériel produit. Ciara n’apprécia pas l’idée, très vite seule survivante, elle continua de se battre et d’entasser les corps du périmètre qu’elle défendait, n’étant pas officiellement envoyée par les Etats-unis, un groupe d’élite tenta de la tuer quand ils tombèrent sur la zone qu’elle défendait depuis plusieurs mois. Capturée, elle fut rapatriée quand on constata sa survie. Durant les grandes émeutes de 2033, elle gagna le statut de grande druidesse aux yeux de la communauté néopaïenne, extrêmement anarchiste et haïssant toute forme de gouvernance depuis qu’elle s’était faite abandonnée en Corée du Nord. C’est une chasseuse depuis son adolescence néanmoins, fille de la Déesse Morrighan, elle voit à travers l’Hologramme en partie et attire les esprits, disciple de Naalnish, elle nourrit une vénération et une rage contre sa propre mère. Elle s’entraine constamment et ses chasses ne seraient qu’un entrainement pour tenter un jour de mettre une correction à la déesse qui l’abandonna trop tôt. Il est plus probable néanmoins que la semi-déesse se sente surtout obligée de défendre les mortels."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-ogshaata-otto","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Le chamane","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Association","Humaine"],"pnj":{"real_name":"Ogshaata « Otto »","nom_verite":"","race":"Humaine","age":"59 ans","origine":"Américaine","statut":"Enders","statut_verite":"Le fléau calamiteux","relations":["Koshaway the Grey"],"source_group":"Association","source_order":9,"identity_keys":["le chamane","ogshaata otto"],"source_verite":[{"label":"Informations Vérité","text":"Ogshaata est né en 1976, dans la réserve de Colorado River. Il se fait surnommer « Otto » par les blancs ayant du mal avec les noms américains. Malgré la création de la grande réserve, Ogshaata est assez peu ouvert au concept même de réserve, tout le continent appartient aux amérindiens selon lui et il installa donc des petites maisons où bon lui semble sans rien demander à personne, afin d’y stocker vivre, munitions et autres ressources nécessaires à ses errances dans le pays. Se baladant dans un smoking blanc rayé toujours impeccable, Ogshaata évite scrupuleusement les grandes villes, et entre toutes, il a une haine profonde pour Los Angeles et Las Vegas qui attirent prodigieusement toutes les créatures occultes par les nœuds d’énergie sur lesquelles ces villes sont fondées. Ogshaata parle librement aux esprits, spectres ou animaux immatériels, élémentaires ou créatures de l’ombre, il communique avec tout. C’est un redoutable combattant et un tireur efficace, entre ses bagues sur ses gants de cuir et la tête de hache sur la crosse de son fusil, il sait parfaitement alterner entre tir, mêlée et combat à mains nus dans la même seconde, étant un excellent combattant maitrisant l’Okichitaw malgré son âge avancé. Très soucieux de son apparence, c’est un homme d’une rare classe, taciturne il n’aime pas parler pour ne rien dire mais n’est pas asocial pour autant, s’il est doté d’un ton très dur, il n’est jamais méprisant. En tant que chasseur, il est un maitre des pactes, s’il tient tant à être si bien habillé, ‘est pour cacher son corps couvert de marques d’esprits, chaque fois qu’il scelle un pacte, son corps est comme marqué au fer rouge et il peut ensuite appeler l’esprit ou être possédé. Certains esprits sont assez perfides et sadiques, d’autres généreux mais il paye souvent les pactes. C’est un vieil homme mais il compte dans le Hunt-15 sans démériter face aux autres, si son physique ou son intelligence eux-mêmes sont loin de ce qu’on les autres chasseurs, l’armée d’esprits qu’il peut invoquer, en revanche, est loin d’être méprisable, il est même possiblement un des chasseurs les plus terrifiant qui soit s’il se déchainait vu les esprits avec lesquels il a des pactes."}],"source_extract":"Le chamane\nLe fléau calamiteux\nNom : Ogshaata « Otto »\nAge : 59 ans\nAffiliations :\nEnders\nNationalité d’origine : Américaine\nEthnie réelle : Humaine\nPersonnages liés :\n Koshaway the Grey\n ?\n___________________________________________________________________________\nInformations Vérité :\nOgshaata est né en 1976, dans la réserve de Colorado River. Il se fait surnommer « Otto » par les\nblancs ayant du mal avec les noms américains.\nMalgré la création de la grande réserve, Ogshaata est assez peu ouvert au concept même de réserve,\ntout le continent appartient aux amérindiens selon lui et il installa donc des petites maisons où bon\nlui semble sans rien demander à personne, afin d’y stocker vivre, munitions et autres ressources\nnécessaires à ses errances dans le pays.\nSe baladant dans un smoking blanc rayé toujours impeccable, Ogshaata évite scrupuleusement les\ngrandes villes, et entre toutes, il a une haine profonde pour Los Angeles et Las Vegas qui attirent\nprodigieusement toutes les créatures occultes par les nœuds d’énergie sur lesquelles ces villes sont\nfondées.\nOgshaata parle librement aux esprits, spectres ou animaux immatériels, élémentaires ou créatures\nde l’ombre, il communique avec tout.\nC’est un redoutable combattant et un tireur efficace, entre ses bagues sur ses gants de cuir et la tête\nde hache sur la crosse de son fusil, il sait parfaitement alterner entre tir, mêlée et combat à mains\nnus dans la même seconde, étant un excellent combattant maitrisant l’Okichitaw malgré son âge\navancé.\nTrès soucieux de son apparence, c’est un homme d’une rare classe, taciturne il n’aime pas parler\npour ne rien dire mais n’est pas asocial pour autant, s’il est doté d’un ton très dur, il n’est jamais\nméprisant.\nEn tant que chasseur, il est un maitre des pactes, s’il tient tant à être si bien habillé, ‘est pour cacher\nson corps couvert de marques d’esprits, chaque fois qu’il scelle un pacte, son corps est comme\nmarqué au fer rouge et il peut ensuite appeler l’esprit ou être possédé. Certains esprits sont assez\nperfides et sadiques, d’autres généreux mais il paye souvent les pactes.\nC’est un vieil homme mais il compte dans le Hunt-15 sans démériter face aux autres, si son physique\nou son intelligence eux-mêmes sont loin de ce qu’on les autres chasseurs, l’armée d’esprits qu’il peut\ninvoquer, en revanche, est loin d’être méprisable, il est même possiblement un des chasseurs les\nplus terrifiant qui soit s’il se déchainait vu les esprits avec lesquels il a des pactes.","source_heading":"Le chamane"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Ogshaata « Otto »"],["Âge","59 ans"],["Affiliations","Enders"],["Nationalité d’origine","Américaine"],["Nature réelle","Humaine"],["Personnages liés","Koshaway the Grey"],["Repère","Le fléau calamiteux"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Ogshaata est né en 1976, dans la réserve de Colorado River. Il se fait surnommer « Otto » par les blancs ayant du mal avec les noms américains. Malgré la création de la grande réserve, Ogshaata est assez peu ouvert au concept même de réserve, tout le continent appartient aux amérindiens selon lui et il installa donc des petites maisons où bon lui semble sans rien demander à personne, afin d’y stocker vivre, munitions et autres ressources nécessaires à ses errances dans le pays. Se baladant dans un smoking blanc rayé toujours impeccable, Ogshaata évite scrupuleusement les grandes villes, et entre toutes, il a une haine profonde pour Los Angeles et Las Vegas qui attirent prodigieusement toutes les créatures occultes par les nœuds d’énergie sur lesquelles ces villes sont fondées. Ogshaata parle librement aux esprits, spectres ou animaux immatériels, élémentaires ou créatures de l’ombre, il communique avec tout. C’est un redoutable combattant et un tireur efficace, entre ses bagues sur ses gants de cuir et la tête de hache sur la crosse de son fusil, il sait parfaitement alterner entre tir, mêlée et combat à mains nus dans la même seconde, étant un excellent combattant maitrisant l’Okichitaw malgré son âge avancé. Très soucieux de son apparence, c’est un homme d’une rare classe, taciturne il n’aime pas parler pour ne rien dire mais n’est pas asocial pour autant, s’il est doté d’un ton très dur, il n’est jamais méprisant. En tant que chasseur, il est un maitre des pactes, s’il tient tant à être si bien habillé, ‘est pour cacher son corps couvert de marques d’esprits, chaque fois qu’il scelle un pacte, son corps est comme marqué au fer rouge et il peut ensuite appeler l’esprit ou être possédé. Certains esprits sont assez perfides et sadiques, d’autres généreux mais il paye souvent les pactes. C’est un vieil homme mais il compte dans le Hunt-15 sans démériter face aux autres, si son physique ou son intelligence eux-mêmes sont loin de ce qu’on les autres chasseurs, l’armée d’esprits qu’il peut invoquer, en revanche, est loin d’être méprisable, il est même possiblement un des chasseurs les plus terrifiant qui soit s’il se déchainait vu les esprits avec lesquels il a des pactes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
